(156319, 8382, 2752, '<td valign="top">simply well stated.Great composition and colors.</td>', 'simply well stated.Great composition and colors.', '2002-11-23 20:47:00.000000', NULL, 1),
(156320, 8420, 772, '<td valign="top">In the ''technology'' challenge, I expected to see a lot of photos of circuit boards.  Knowing this, I believe that these photos need to be done more creatively in an attempt to make them stand out.  How could you have made this photograph more impactive?  If you are new to the challenge concept, one thing you may consider is ASSUMING that there will be several other photos like yours each week.  In many cases, there are!  With this in mind, you need to create impact....  - setzler</td>', 'In the ''technology'' challenge, I expected to see a lot of photos of circuit boards.  Knowing this, I believe that these photos need to be done more creatively in an attempt to make them stand out.  How could you have made this photograph more impactive?  If you are new to the challenge concept, one thing you may consider is ASSUMING that there will be several other photos like yours each week.  In many cases, there are!  With this in mind, you need to create impact....  - setzler', '2002-11-18 12:17:00.000000', NULL, 1),
(156321, 8420, 2170, '<td valign="top">Before and after what?  One is a modem and the other is a memory card.  I don''t really see how  the two relate.</td>', 'Before and after what?  One is a modem and the other is a memory card.  I don''t really see how  the two relate.', '2002-11-18 17:36:00.000000', NULL, 1),
(156322, 8420, 4821, '<td valign="top">good lighting.  but uncreative.</td>', 'good lighting.  but uncreative.', '2002-11-18 21:16:00.000000', NULL, 1),
(156323, 8420, 4998, '<td valign="top">nice shot, good lighting.</td>', 'nice shot, good lighting.', '2002-11-18 21:18:00.000000', NULL, 1),
(156324, 8420, 4832, '<td valign="top">Too simple, nothing really out of the ordinary with this picture. Besides, that''s a modem, not a large memory card. =)</td>', 'Too simple, nothing really out of the ordinary with this picture. Besides, that''s a modem, not a large memory card. =)', '2002-11-18 22:27:00.000000', NULL, 1),
