(156330, 8420, 4648, '<td valign="top">I don''t understand the title, I''m not real technically inclined, but this is a very clear and concise picture.  Great colors with good centering.  Not really exciting but technically great shot.  PTL</td>', 'I don''t understand the title, I''m not real technically inclined, but this is a very clear and concise picture.  Great colors with good centering.  Not really exciting but technically great shot.  PTL', '2002-11-23 12:30:00.000000', NULL, 1),
(156331, 8420, 5070, '<td valign="top">Nice try but unless I''m mistaken, the board on the left isn''t the  equivalent of memory (e.g., RAM). A better comparison would have been between a hard drive and the IBM microdrive.</td>', 'Nice try but unless I''m mistaken, the board on the left isn''t the  equivalent of memory (e.g., RAM). A better comparison would have been between a hard drive and the IBM microdrive.', '2002-11-23 14:13:00.000000', NULL, 1),
(156332, 8421, 4625, '<td valign="top">Haha! Way cool. Nice use of humor, while still taking an outstanding shot. well done.</td>', 'Haha! Way cool. Nice use of humor, while still taking an outstanding shot. well done.', '2002-11-18 01:27:00.000000', NULL, 1),
(156333, 8421, 4077, '<td valign="top">Hmm... think this is the better of the two "candle''s with switches embedded" image.</td>', 'Hmm... think this is the better of the two "candle''s with switches embedded" image.', '2002-11-18 04:42:00.000000', NULL, 1),
(156334, 8421, 472, '<td valign="top">i give this an 8 for concept and composition. lighting is uninteresting, tho. otherwise could have been a 10.  looks like u used on-camera flash?  mag99</td>', 'i give this an 8 for concept and composition. lighting is uninteresting, tho. otherwise could have been a 10.  looks like u used on-camera flash?  mag99', '2002-11-18 08:25:00.000000', NULL, 1),
