(156336, 8421, 3506, '<td valign="top">Another nicely done switchable candle shot.  :)  (7)</td>', 'Another nicely done switchable candle shot.  :)  (7)', '2002-11-18 10:17:00.000000', NULL, 1),
(156337, 8421, 2170, '<td valign="top">Nice idea.  Too bad someone else came up with the same concept.  I''m not sure how well this speaks to the topic, though.</td>', 'Nice idea.  Too bad someone else came up with the same concept.  I''m not sure how well this speaks to the topic, though.', '2002-11-18 13:06:00.000000', NULL, 1),
(156338, 8421, 3942, '<td valign="top">Creative and nice idea ;-) But IMHO the shot doesn''t look very interesting. I don''t like the background (parquet) and the lighting. Maybe the other voters think completely different...   5 (for creativity) - nds</td>', 'Creative and nice idea ;-) But IMHO the shot doesn''t look very interesting. I don''t like the background (parquet) and the lighting. Maybe the other voters think completely different...   5 (for creativity) - nds', '2002-11-18 13:56:00.000000', NULL, 1),
