(156345, 8421, 4510, '<td valign="top">CLEVER IDEA AND NICELY DONE !!</td>', 'CLEVER IDEA AND NICELY DONE !!', '2002-11-19 06:03:00.000000', NULL, 1),
(156346, 8421, 4648, '<td valign="top">Is this a paradigm shift I''ve heard so much about?  If that''s all the candel that melted it didn''t take you long to get the great shot.  I love the subject, how well you met the challenge, the focus, the lighting, the color, the humor.  Most of all the humor.  Thanks so much for a job well done.  PTL</td>', 'Is this a paradigm shift I''ve heard so much about?  If that''s all the candel that melted it didn''t take you long to get the great shot.  I love the subject, how well you met the challenge, the focus, the lighting, the color, the humor.  Most of all the humor.  Thanks so much for a job well done.  PTL', '2002-11-19 16:54:00.000000', NULL, 1),
(156347, 8421, 4514, '<td valign="top">Very cute and good capture.  Need to speed up the shutter speed to see the full color of the candle flame.</td>', 'Very cute and good capture.  Need to speed up the shutter speed to see the full color of the candle flame.', '2002-11-20 01:04:00.000000', NULL, 1),
(156348, 8421, 2241, '<td valign="top">very interesting combination of three technologies: printing, candle, and chip</td>', 'very interesting combination of three technologies: printing, candle, and chip', '2002-11-20 10:50:00.000000', NULL, 1),
(156349, 8421, 4927, '<td valign="top">A superb photo. I loved how you made a "hybrid technology" by combining the new and the old. The camera angle and book really add to the overall composition as well.</td>', 'A superb photo. I loved how you made a "hybrid technology" by combining the new and the old. The camera angle and book really add to the overall composition as well.', '2002-11-20 14:30:00.000000', NULL, 1),
(156350, 8421, 3936, '<td valign="top">Clever.  Good exposure and lighting.  Book leads the eye out of the picture a bit, but the shot would have been so much less without it.  Not sure what could have been done different.  Overall 8</td>', 'Clever.  Good exposure and lighting.  Book leads the eye out of the picture a bit, but the shot would have been so much less without it.  Not sure what could have been done different.  Overall 8', '2002-11-20 18:50:00.000000', NULL, 1),
(156351, 8421, 3447, '<td valign="top">Not only a clever idea, but an excellent photograph.    7     JEM</td>', 'Not only a clever idea, but an excellent photograph.    7     JEM', '2002-11-22 20:55:00.000000', NULL, 1),
(156352, 8423, 1856, '<td valign="top">LOL...I''m fascinated with this view of lights and architecture too.  I think this may have been a tad better had the weather cooperated with you and given you a gorgeous sky.  Lisa</td>', 'LOL...I''m fascinated with this view of lights and architecture too.  I think this may have been a tad better had the weather cooperated with you and given you a gorgeous sky.  Lisa', '2002-11-18 10:59:00.000000', NULL, 1),
(156353, 8423, 1280, '<td valign="top">Nice!  Simple and uncluttered.  Would like to see a little color in the sky,  but what can you do?  LOL  6   Anyway, good luck in the challenge.  Grayce</td>', 'Nice!  Simple and uncluttered.  Would like to see a little color in the sky,  but what can you do?  LOL  6   Anyway, good luck in the challenge.  Grayce', '2002-11-20 00:08:00.000000', NULL, 1),
