(156673, 8452, 4536, '<td valign="top">I find myself wanting to see more of what he is doing, more of his hands.<br/>Maybe crop some off the top to get rid of the distracting box and blue object?<br/>Interesting photo.</td>', 'I find myself wanting to see more of what he is doing, more of his hands.Maybe crop some off the top to get rid of the distracting box and blue object?Interesting photo.', '2002-11-21 14:07:00.000000', NULL, 1),
(156674, 8452, 1019, '<td valign="top">Takes me back to those dreaded days in the chem lab--good idea  andrewm</td>', 'Takes me back to those dreaded days in the chem lab--good idea  andrewm', '2002-11-21 23:49:00.000000', NULL, 1),
