INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(156901, 8478, 2344, '<td valign="top">Nice! One of the better pictures IMO. Look how dusty that plug is!-8</td>', 'Nice! One of the better pictures IMO. Look how dusty that plug is!-8', '2002-11-18 07:43:00.000000', NULL, 1),
(156902, 8478, 92, '<td valign="top">Great job ! Shiiizzzam</td>', 'Great job ! Shiiizzzam', '2002-11-18 08:35:00.000000', NULL, 1),
(156903, 8478, 3127, '<td valign="top">Spectacular macro shot. I really like this one!</td>', 'Spectacular macro shot. I really like this one!', '2002-11-18 13:15:00.000000', NULL, 1),
(156904, 8478, 5083, '<td valign="top">Love the focusing effect!</td>', 'Love the focusing effect!', '2002-11-18 14:59:00.000000', NULL, 1),
(156905, 8478, 327, '<td valign="top">Exellent!! Love that blue, not crazy for the glare/flash &amp;lt;?&amp;gt; at the bottom. Job well done. Justine.</td>', 'Exellent!! Love that blue, not crazy for the glare/flash &lt;?&gt; at the bottom. Job well done. Justine.', '2002-11-18 19:03:00.000000', NULL, 1),
(156906, 8478, 4267, '<td valign="top">a technically superb shot.... great lighting!!!, focus, and cropping... it''s kind of like the scarecrow in Oz  and Neal Peart of Rush though... it needs some heart...</td>', 'a technically superb shot.... great lighting!!!, focus, and cropping... it''s kind of like the scarecrow in Oz  and Neal Peart of Rush though... it needs some heart...', '2002-11-19 00:01:00.000000', NULL, 1),
(156907, 8478, 3540, '<td valign="top">This picture is all about DOF, which is extremely shallow, even for a macro. - Inspzil</td>', 'This picture is all about DOF, which is extremely shallow, even for a macro. - Inspzil', '2002-11-19 05:12:00.000000', NULL, 1),
(156908, 8478, 4985, '<td valign="top">This is very good. I like the overall composition. I wish I could take pictures that nice and close.</td>', 'This is very good. I like the overall composition. I wish I could take pictures that nice and close.', '2002-11-19 11:49:00.000000', NULL, 1),
(156909, 8478, 2343, '<td valign="top">nice stock photo</td>', 'nice stock photo', '2002-11-19 16:26:00.000000', NULL, 1),
(156910, 8478, 2170, '<td valign="top">Beautiful and well-lit.  I love the focus but am sure other people are complaining.</td>', 'Beautiful and well-lit.  I love the focus but am sure other people are complaining.', '2002-11-19 22:50:00.000000', NULL, 1),
(156911, 8478, 4648, '<td valign="top">Connections and who you know.  It''s a good thing thiese are submitted in anonimity until is''t all over.  Great tech point but out of focus.  Good idea, just not so good execution.  Tight crop.  Pulling back and showing more might have helped the focus.  Best of luck.  PTL</td>', 'Connections and who you know.  It''s a good thing thiese are submitted in anonimity until is''t all over.  Great tech point but out of focus.  Good idea, just not so good execution.  Tight crop.  Pulling back and showing more might have helped the focus.  Best of luck.  PTL', '2002-11-19 23:30:00.000000', NULL, 1),
(156912, 8478, 3380, '<td valign="top">excellent detail, compostion, and color lines</td>', 'excellent detail, compostion, and color lines', '2002-11-20 01:08:00.000000', NULL, 1),
(156913, 8478, 2716, '<td valign="top">Nice depth of field,  I like how the centre pins are in focus.  Jacko.  7</td>', 'Nice depth of field,  I like how the centre pins are in focus.  Jacko.  7', '2002-11-20 06:12:00.000000', NULL, 1),
(156914, 8478, 4210, '<td valign="top">I like the blue, and I think the dof works for this photo.</td>', 'I like the blue, and I think the dof works for this photo.', '2002-11-20 12:01:00.000000', NULL, 1),
(156915, 8478, 4514, '<td valign="top">Oh man this would have been a great shot with DOF.  Need to up the F number if possible<br/></td>', 'Oh man this would have been a great shot with DOF.  Need to up the F number if possible', '2002-11-20 21:49:00.000000', NULL, 1),
(156916, 8478, 4615, '<td valign="top">Looks like a hang over from last weeks macro challenge.  For me, the depth of field is too narrow.</td>', 'Looks like a hang over from last weeks macro challenge.  For me, the depth of field is too narrow.', '2002-11-20 22:46:00.000000', NULL, 1),
(156917, 8478, 2488, '<td valign="top">This could go into MACRO challenge as well!!The FOD shold have been attended to a litlle better</td>', 'This could go into MACRO challenge as well!!The FOD shold have been attended to a litlle better', '2002-11-21 07:41:00.000000', NULL, 1),
(156918, 8478, 3087, '<td valign="top">The DOF in this ROCKS and the combination of blacks, greys/ silvers and that blue are just perfect. Not 100% sure of cropping - something about very top left of frame feels not quite right - but overall this is an excellent shot and much more than just a photo of a bit of kit...<br/>9, Kavey<br/>Sun 24th bumping to 10... Kavey</td>', 'The DOF in this ROCKS and the combination of blacks, greys/ silvers and that blue are just perfect. Not 100% sure of cropping - something about very top left of frame feels not quite right - but overall this is an excellent shot and much more than just a photo of a bit of kit...9, KaveySun 24th bumping to 10... Kavey', '2002-11-22 09:04:00.000000', NULL, 1),
(156919, 8478, 2989, '<td valign="top">The white blur at the bottom of this image is a bit distracting, but it''s a nice focused solid shot.</td>', 'The white blur at the bottom of this image is a bit distracting, but it''s a nice focused solid shot.', '2002-11-22 09:14:00.000000', NULL, 1),
(156920, 8478, 5070, '<td valign="top">Attractive macro.</td>', 'Attractive macro.', '2002-11-23 15:17:00.000000', NULL, 1),
(156921, 8478, 2170, '<td valign="top">Congrats on a great finish!  That 7i is sure sweet!  ;)  Rob</td>', 'Congrats on a great finish!  That 7i is sure sweet!  ;)  Rob', '2002-11-25 00:36:00.000000', NULL, 0),
(156922, 8482, 2170, '<td valign="top">The angle and background are very distracting.  This shot could have been staged so much better.  What is the yearbook in the back for?  I don''t see how it relates to the topic, or other items in the photo, at all.</td>', 'The angle and background are very distracting.  This shot could have been staged so much better.  What is the yearbook in the back for?  I don''t see how it relates to the topic, or other items in the photo, at all.', '2002-11-18 17:32:00.000000', NULL, 1),
(156923, 8482, 772, '<td valign="top">I understand your comparison of technologies in this shot... The angle and composition of this particular photo doesn''t really grab me.  - setzler</td>', 'I understand your comparison of technologies in this shot... The angle and composition of this particular photo doesn''t really grab me.  - setzler', '2002-11-19 13:00:00.000000', NULL, 1),
(156924, 8482, 2866, '<td valign="top">Should have spent more time on this. -4-</td>', 'Should have spent more time on this. -4-', '2002-11-19 20:04:00.000000', NULL, 1),
(156925, 8482, 2716, '<td valign="top">Too bad you didn''t have an 8-track lol.  Nice shot.  Jacko</td>', 'Too bad you didn''t have an 8-track lol.  Nice shot.  Jacko', '2002-11-20 06:21:00.000000', NULL, 1),
(156926, 8482, 4648, '<td valign="top">I love your couch but I bet a lot have said should have placed on a better surface.  Or don''t like back ground and base.  Yes their right but why add insult to injury.  You''ve probably heard enough bad.  What is good.    Thelight is fairly good.  The focus is soft and this works here for me.  I like your subjects.  Good arrangement of the items.  I like the magazine in the background.  It adds to it very much.  Great imput.  You already know what to do to make it better.  Best in the future.  PTL</td>', 'I love your couch but I bet a lot have said should have placed on a better surface.  Or don''t like back ground and base.  Yes their right but why add insult to injury.  You''ve probably heard enough bad.  What is good.    Thelight is fairly good.  The focus is soft and this works here for me.  I like your subjects.  Good arrangement of the items.  I like the magazine in the background.  It adds to it very much.  Great imput.  You already know what to do to make it better.  Best in the future.  PTL', '2002-11-20 17:17:00.000000', NULL, 1),
(156927, 8482, 4514, '<td valign="top">Hmmmmmm.</td>', 'Hmmmmmm.', '2002-11-21 10:53:00.000000', NULL, 1),
(156928, 8482, 671, '<td valign="top">poor composition</td>', 'poor composition', '2002-11-22 19:09:00.000000', NULL, 1),
(156929, 8482, 5070, '<td valign="top">The sofa in the background spoils the photo.</td>', 'The sofa in the background spoils the photo.', '2002-11-23 14:38:00.000000', NULL, 1),
(156930, 8482, 806, '<td valign="top">the table and colors of the sofa (?) are distracting. placing a blanket or something under the set up would help this... the table alone would have been okay actually.. just the sofa needs to be removed/blocked, and maybe grouping the objects closer together so that the look like a collection rather than a display.</td>', 'the table and colors of the sofa (?) are distracting. placing a blanket or something under the set up would help this... the table alone would have been okay actually.. just the sofa needs to be removed/blocked, and maybe grouping the objects closer together so that the look like a collection rather than a display.', '2002-11-23 21:41:00.000000', NULL, 1),
(156931, 8483, 674, '<td valign="top">Technically correct , exposure, focus, saturation , contrast. 8<br/>Good composition.  <br/>Tells a story or creates a mood <br/>      Impact to the viewer  technically excellent but no wow factor<br/>Relevance to the Challenge 9<br/>Overall 8<br/>sulamk<br/></td>', 'Technically correct , exposure, focus, saturation , contrast. 8Good composition.  Tells a story or creates a mood       Impact to the viewer  technically excellent but no wow factorRelevance to the Challenge 9Overall 8sulamk', '2002-11-18 01:10:00.000000', NULL, 1),
(156932, 8483, 4514, '<td valign="top">Very Nice</td>', 'Very Nice', '2002-11-18 01:15:00.000000', NULL, 1),
(156933, 8483, 4737, '<td valign="top">looks a little distorted. nice shot though<br/></td>', 'looks a little distorted. nice shot though', '2002-11-18 03:16:00.000000', NULL, 1),
(156934, 8483, 3900, '<td valign="top">The last time I looked pulleys were not oval.  Careful with that perspective when resizing your image.  Otherwise not a bad shot.</td>', 'The last time I looked pulleys were not oval.  Careful with that perspective when resizing your image.  Otherwise not a bad shot.', '2002-11-18 06:23:00.000000', NULL, 1),
(156935, 8483, 327, '<td valign="top">Neat shot. Good work. Justine</td>', 'Neat shot. Good work. Justine', '2002-11-18 16:44:00.000000', NULL, 1),
(156936, 8483, 2488, '<td valign="top">Looks like a museum piece-clean an'' speckless.Nice job!!</td>', 'Looks like a museum piece-clean an'' speckless.Nice job!!', '2002-11-18 17:17:00.000000', NULL, 1),
(156937, 8483, 3669, '<td valign="top">This picture looks stretched to me.  The gears are oval and shouldn''t they be round?  That''s the only thing that bothers me.  Otherwise the picture meets the challenge and is in focus</td>', 'This picture looks stretched to me.  The gears are oval and shouldn''t they be round?  That''s the only thing that bothers me.  Otherwise the picture meets the challenge and is in focus', '2002-11-18 18:03:00.000000', NULL, 1),
(156938, 8483, 4648, '<td valign="top">Looks like an old either radio tuner or victrola motor.  Good clear and sharp focus.  Technically right on.  Solid 7 just lacks "wow" for me.  Ptl.</td>', 'Looks like an old either radio tuner or victrola motor.  Good clear and sharp focus.  Technically right on.  Solid 7 just lacks "wow" for me.  Ptl.', '2002-11-18 20:49:00.000000', NULL, 1),
(156939, 8483, 2716, '<td valign="top">Nice angles and circles.  Is it possible the image was flattened, height wise, during manipulation?  Looks a bit off.  I like anyways.  jacko</td>', 'Nice angles and circles.  Is it possible the image was flattened, height wise, during manipulation?  Looks a bit off.  I like anyways.  jacko', '2002-11-18 20:53:00.000000', NULL, 1),
(156940, 8483, 4821, '<td valign="top">looks warped.</td>', 'looks warped.', '2002-11-18 21:35:00.000000', NULL, 1),
(156941, 8483, 1280, '<td valign="top">Wow...sure has lots of moving parts to maintain.   I do wonder what it performs or accomplishes. <br/>Your image is good, and interesting.  It also meets the challenge nicely.  Good luck in the challenge!  7 Grayce</td>', 'Wow...sure has lots of moving parts to maintain.   I do wonder what it performs or accomplishes. Your image is good, and interesting.  It also meets the challenge nicely.  Good luck in the challenge!  7 Grayce', '2002-11-20 14:25:00.000000', NULL, 1),
(156942, 8483, 4811, '<td valign="top">I''m wondering why the image looks compressed vertically, Its a great photo of a complex machine but it would also be nice for the aspect ratio of the image to look normal (ie, have the wheels be circle shaped instead of oval)</td>', 'I''m wondering why the image looks compressed vertically, Its a great photo of a complex machine but it would also be nice for the aspect ratio of the image to look normal (ie, have the wheels be circle shaped instead of oval)', '2002-11-20 22:15:00.000000', NULL, 1),
(156943, 8483, 2667, '<td valign="top">nice image, but yes, i''m gonna gig you on the stretching thing... i stretch my photos for almost every challenge, I just dont do it by much. depending on the subject, you can usually get away with 10 to 15 pixels of stretch (or squeeze) in one direction. After that, it gets kinda iffy.</td>', 'nice image, but yes, i''m gonna gig you on the stretching thing... i stretch my photos for almost every challenge, I just dont do it by much. depending on the subject, you can usually get away with 10 to 15 pixels of stretch (or squeeze) in one direction. After that, it gets kinda iffy.', '2002-11-23 00:23:00.000000', NULL, 1),
(156944, 8485, 4267, '<td valign="top">now thats a dinosaur!</td>', 'now thats a dinosaur!', '2002-11-18 01:30:00.000000', NULL, 1),
(156945, 8485, 4077, '<td valign="top">Not entirely sure I''d agree with the title. (Kinda hope it''s tongue in cheek.)</td>', 'Not entirely sure I''d agree with the title. (Kinda hope it''s tongue in cheek.)', '2002-11-18 04:58:00.000000', NULL, 1),
(156946, 8485, 3900, '<td valign="top">I''ll bet you had to dust that sucker off.  Oh, whatever happened to my VIC-20 with the cassette drive, what a smoker that was!!!???</td>', 'I''ll bet you had to dust that sucker off.  Oh, whatever happened to my VIC-20 with the cassette drive, what a smoker that was!!!???', '2002-11-18 06:31:00.000000', NULL, 1),
(156947, 8485, 2567, '<td valign="top">Nice shot.  Like the color and composition.</td>', 'Nice shot.  Like the color and composition.', '2002-11-18 11:56:00.000000', NULL, 1),
(156948, 8485, 5064, '<td valign="top">LIke the blue lighting</td>', 'LIke the blue lighting', '2002-11-18 12:46:00.000000', NULL, 1),
(156949, 8485, 5142, '<td valign="top">MY FIRST COMPUTER!!! NICE PIC!! BOULDER DASH RULED<br/></td>', 'MY FIRST COMPUTER!!! NICE PIC!! BOULDER DASH RULED', '2002-11-18 13:48:00.000000', NULL, 1),
(156950, 8485, 2170, '<td valign="top">A lot of macro shots again this week.  People must be stuck in macro mode.  Ah well, nice photo.  i enjoy the color -- was that done in lighting or post-processing?</td>', 'A lot of macro shots again this week.  People must be stuck in macro mode.  Ah well, nice photo.  i enjoy the color -- was that done in lighting or post-processing?', '2002-11-18 17:24:00.000000', NULL, 1),
(156951, 8485, 327, '<td valign="top">lol hang on to that!!</td>', 'lol hang on to that!!', '2002-11-18 19:19:00.000000', NULL, 1),
(156952, 8485, 2861, '<td valign="top">That''s the best I''ve seen one of those look.</td>', 'That''s the best I''ve seen one of those look.', '2002-11-18 20:23:00.000000', NULL, 1),
(156953, 8485, 4793, '<td valign="top">Great shot, love it.</td>', 'Great shot, love it.', '2002-11-18 20:34:00.000000', NULL, 1),
(156954, 8485, 92, '<td valign="top">LOVE the color choice !!!! Really nicely done ! Shiiizzzam</td>', 'LOVE the color choice !!!! Really nicely done ! Shiiizzzam', '2002-11-18 23:34:00.000000', NULL, 1),
(156955, 8485, 573, '<td valign="top">A good photo in all areas, but the blue overall cast does not do anything for the picture, in my opinion.</td>', 'A good photo in all areas, but the blue overall cast does not do anything for the picture, in my opinion.', '2002-11-19 11:14:00.000000', NULL, 1),
(156956, 8485, 5202, '<td valign="top">Beautiful lighting</td>', 'Beautiful lighting', '2002-11-19 15:33:00.000000', NULL, 1),
(156957, 8485, 4411, '<td valign="top">Crikey - haven''t seen one of these in years. The Spectrum still rules though!</td>', 'Crikey - haven''t seen one of these in years. The Spectrum still rules though!', '2002-11-20 12:52:00.000000', NULL, 1),
(156958, 8485, 3575, '<td valign="top">Oh My Gosh! The Commodore 64! Don''t remember it being so blue :) A whopping 64 k of RAM -- and what did they cost? Thanks for the memories. This is a very good photograph with emotional impact.</td>', 'Oh My Gosh! The Commodore 64! Don''t remember it being so blue :) A whopping 64 k of RAM -- and what did they cost? Thanks for the memories. This is a very good photograph with emotional impact.', '2002-11-20 19:55:00.000000', NULL, 1),
(156959, 8485, 4514, '<td valign="top">Holy smoke.  Break out Summer Games for this Commodore 64.  Does this still work?  Good color.  Nice composition.</td>', 'Holy smoke.  Break out Summer Games for this Commodore 64.  Does this still work?  Good color.  Nice composition.', '2002-11-21 10:49:00.000000', NULL, 1),
(156960, 8485, 2989, '<td valign="top">I love the bright blue colors but the prespective leaves too much to the imagination.</td>', 'I love the bright blue colors but the prespective leaves too much to the imagination.', '2002-11-22 09:12:00.000000', NULL, 1),
