(156966, 8486, 4821, '<td valign="top">at first I thought this was a black and white image.  I was fooled. 7</td>', 'at first I thought this was a black and white image.  I was fooled. 7', '2002-11-18 20:39:00.000000', NULL, 1),
(156967, 8486, 4585, '<td valign="top">Outstanding!</td>', 'Outstanding!', '2002-11-18 22:12:00.000000', NULL, 1),
