(156969, 8486, 4805, '<td valign="top">I like the DOF here a lot. I''m sure you''ll get a lot of comments wishing it was all in focus. Ignore them. It''s great. Very nice lighting.</td>', 'I like the DOF here a lot. I''m sure you''ll get a lot of comments wishing it was all in focus. Ignore them. It''s great. Very nice lighting.', '2002-11-19 15:11:00.000000', NULL, 1),
(156970, 8486, 3697, '<td valign="top">I like your DOF, really draws the eye to the cable ends. Nice work.</td>', 'I like your DOF, really draws the eye to the cable ends. Nice work.', '2002-11-19 18:28:00.000000', NULL, 1),
(156971, 8486, 2170, '<td valign="top">Great close-up.  The lighting (especially on the left) is un even.  If the lighting could be straightened out, this could easily be a stock shot.  Nicely done.</td>', 'Great close-up.  The lighting (especially on the left) is un even.  If the lighting could be straightened out, this could easily be a stock shot.  Nicely done.', '2002-11-19 23:07:00.000000', NULL, 1),
(156972, 8486, 3859, '<td valign="top">I like the simplicity of this.</td>', 'I like the simplicity of this.', '2002-11-20 00:07:00.000000', NULL, 1),
(156973, 8486, 2352, '<td valign="top">Perhaps a bit of color with the lighting might have given it more umph...</td>', 'Perhaps a bit of color with the lighting might have given it more umph...', '2002-11-20 01:24:00.000000', NULL, 1),
