(157400, 8520, 5070, '<td valign="top">Amazing shot.</td>', 'Amazing shot.', '2002-11-23 13:29:00.000000', NULL, 1),
(157401, 8520, 2553, '<td valign="top">An awesome, amazing shot.  The center composition works great. I really like the abstract feel to it, with all the lines and angles, as well as the areas of light and dark.  Either your timing is incredible, or you waited through a lot of shots to get this!  lhall</td>', 'An awesome, amazing shot.  The center composition works great. I really like the abstract feel to it, with all the lines and angles, as well as the areas of light and dark.  Either your timing is incredible, or you waited through a lot of shots to get this!  lhall', '2002-11-24 07:54:00.000000', NULL, 1),
(157402, 8520, 2221, '<td valign="top">Nice picture of someone elses art... no, no just kidding ;-) Great composition! I also like the colour tone. A bit overexposed, because the propellers disappear in the sky and the "nose" of the plane loses its edges. -stephan</td>', 'Nice picture of someone elses art... no, no just kidding ;-) Great composition! I also like the colour tone. A bit overexposed, because the propellers disappear in the sky and the "nose" of the plane loses its edges. -stephan', '2002-11-24 08:46:00.000000', NULL, 1),
(157403, 8520, 1280, '<td valign="top">Wow!  THis is a great perspective, and quite an amazing image.  The only improvement I would like to see would be to sharpen it a little.  But anyway this is very, very good!  Grayce</td>', 'Wow!  THis is a great perspective, and quite an amazing image.  The only improvement I would like to see would be to sharpen it a little.  But anyway this is very, very good!  Grayce', '2002-11-24 16:51:00.000000', NULL, 1),
