(157414, 8520, 5121, '<td valign="top">Gave this one a top mark. Knew it''d come somewhere up there (excuse the pun).</td>', 'Gave this one a top mark. Knew it''d come somewhere up there (excuse the pun).', '2002-11-25 13:13:00.000000', NULL, 0),
