(157485, 8529, 4832, '<td valign="top">Nice use of B&amp;W.</td>', 'Nice use of B&W.', '2002-11-18 23:09:00.000000', NULL, 1),
(157486, 8529, 2170, '<td valign="top">Beautiful!  And very unexpected.  Crisp, clean...wish I had done it!  Did you try to soften the light to avoid the harsher shadows?  Still -- a gorgeous picture.</td>', 'Beautiful!  And very unexpected.  Crisp, clean...wish I had done it!  Did you try to soften the light to avoid the harsher shadows?  Still -- a gorgeous picture.', '2002-11-19 22:17:00.000000', NULL, 1),
(157487, 8529, 4514, '<td valign="top">Intresting.  May want to try to supress the sharp light on the tip of the gun by using a soft box light or if you do not have one, try placing a piece of thin white cloth in front of the light source.</td>', 'Intresting.  May want to try to supress the sharp light on the tip of the gun by using a soft box light or if you do not have one, try placing a piece of thin white cloth in front of the light source.', '2002-11-20 00:25:00.000000', NULL, 1),
(157488, 8529, 4210, '<td valign="top">Very clean. I like the grayscale.</td>', 'Very clean. I like the grayscale.', '2002-11-20 02:53:00.000000', NULL, 1),
(157489, 8529, 3540, '<td valign="top">Very well done.  My fav so far.  Nice lighting, framing, B&amp;W was a fine choice.  On the downside, well there is no downside.  Great job - Inspzil</td>', 'Very well done.  My fav so far.  Nice lighting, framing, B&W was a fine choice.  On the downside, well there is no downside.  Great job - Inspzil', '2002-11-20 05:16:00.000000', NULL, 1),
(157490, 8529, 2716, '<td valign="top">I really like the tones of this B&amp;W.  Great framing.  Jacko 7.  The subject is a little uninteresting.  maybe I should pick up painting.</td>', 'I really like the tones of this B&W.  Great framing.  Jacko 7.  The subject is a little uninteresting.  maybe I should pick up painting.', '2002-11-20 06:18:00.000000', NULL, 1),
(157491, 8529, 2488, '<td valign="top">Nice detail,great light!!</td>', 'Nice detail,great light!!', '2002-11-20 08:51:00.000000', NULL, 1),
(157492, 8529, 2752, '<td valign="top">great shot of an airbrush..good composition and use of black and white</td>', 'great shot of an airbrush..good composition and use of black and white', '2002-11-20 23:59:00.000000', NULL, 1),
(157493, 8529, 4817, '<td valign="top">Great, but just a bit too dark, I think. 8</td>', 'Great, but just a bit too dark, I think. 8', '2002-11-21 10:01:00.000000', NULL, 1),
(157494, 8529, 4430, '<td valign="top">Very nice b/w.  Very surprised that this came across as a great b/w, never would have thunk it.</td>', 'Very nice b/w.  Very surprised that this came across as a great b/w, never would have thunk it.', '2002-11-21 23:34:00.000000', NULL, 1),
(157495, 8529, 1019, '<td valign="top">well lit superb focus and well thought out--a high quality macro study--well done  andrewm</td>', 'well lit superb focus and well thought out--a high quality macro study--well done  andrewm', '2002-11-21 23:50:00.000000', NULL, 1),
(157496, 8529, 5149, '<td valign="top">Nice sharp image. Great job with your lighting too for such a tough subject to light without hotspots.</td>', 'Nice sharp image. Great job with your lighting too for such a tough subject to light without hotspots.', '2002-11-22 21:09:00.000000', NULL, 1),
(157497, 8529, 4648, '<td valign="top">Very clean shot.  Nice crop.  Like the focus...does this pic well.  PTL</td>', 'Very clean shot.  Nice crop.  Like the focus...does this pic well.  PTL', '2002-11-23 12:07:00.000000', NULL, 1),
(157498, 8529, 4805, '<td valign="top">I quite like this. Good contrast, good black and white. Focus is bang on. The upper left corner seems a bit empty but I don''t know how else you''d compose it without losing other aspects of the photo. One of my top 5 this week.</td>', 'I quite like this. Good contrast, good black and white. Focus is bang on. The upper left corner seems a bit empty but I don''t know how else you''d compose it without losing other aspects of the photo. One of my top 5 this week.', '2002-11-24 18:07:00.000000', NULL, 1),
(157499, 8530, 4625, '<td valign="top">nice shot. I tried a shot similar to this with two buildings near me but couldn''t get it to look good. You did a great job, it looks really good.</td>', 'nice shot. I tried a shot similar to this with two buildings near me but couldn''t get it to look good. You did a great job, it looks really good.', '2002-11-18 01:29:00.000000', NULL, 1),
(157500, 8530, 4615, '<td valign="top">its a difference in style, not technology, that is being reflected.</td>', 'its a difference in style, not technology, that is being reflected.', '2002-11-18 08:49:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(157501, 8530, 4906, '<td valign="top">Nice idea but the view through the window detracts from the old building.</td>', 'Nice idea but the view through the window detracts from the old building.', '2002-11-18 08:50:00.000000', NULL, 1),
(157502, 8530, 4793, '<td valign="top">Nice photo.</td>', 'Nice photo.', '2002-11-18 20:48:00.000000', NULL, 1),
(157503, 8530, 4648, '<td valign="top">How unique and a fantastic pic.  Clear, interesting, right on for challenge, interesting, good crop job.  Can''t say much more than really great 8.  PTL  Had to come back and up it one.  The more I look at it.</td>', 'How unique and a fantastic pic.  Clear, interesting, right on for challenge, interesting, good crop job.  Can''t say much more than really great 8.  PTL  Had to come back and up it one.  The more I look at it.', '2002-11-18 20:50:00.000000', NULL, 1),
(157504, 8530, 4998, '<td valign="top">technology?</td>', 'technology?', '2002-11-18 21:56:00.000000', NULL, 1),
(157505, 8530, 4585, '<td valign="top">Outstanding!...I really like this...9</td>', 'Outstanding!...I really like this...9', '2002-11-18 22:40:00.000000', NULL, 1),
(157506, 8530, 5202, '<td valign="top">marvelous</td>', 'marvelous', '2002-11-19 15:44:00.000000', NULL, 1),
(157507, 8530, 3575, '<td valign="top">This is a great reflection and very meaninful comparing the old and new. I suppose technology helped build the new building. Is there no sky?</td>', 'This is a great reflection and very meaninful comparing the old and new. I suppose technology helped build the new building. Is there no sky?', '2002-11-19 20:32:00.000000', NULL, 1),
