(157564, 8536, 1280, '<td valign="top">Nice colors, and composition.</td>', 'Nice colors, and composition.', '2002-11-20 00:17:00.000000', NULL, 1),
(157565, 8536, 4514, '<td valign="top">I am lost.  What does tha name have to do with it?  Are you saying that the fan technology that was designed long ago is still alive and well????</td>', 'I am lost.  What does tha name have to do with it?  Are you saying that the fan technology that was designed long ago is still alive and well????', '2002-11-20 00:34:00.000000', NULL, 1),
(157566, 8536, 4906, '<td valign="top">Like the colour and the blur effect on the blades. Would have been better if the nose had been sharper. Findthe rear of the fan a little distracting too.</td>', 'Like the colour and the blur effect on the blades. Would have been better if the nose had been sharper. Findthe rear of the fan a little distracting too.', '2002-11-20 06:04:00.000000', NULL, 1),
