(157624, 8538, 3540, '<td valign="top">Well done Manic.  You''ve officially placed higher than me in a challenge, so I can''t feel like I''ve got one up on you anymore.  I never did feel that way anyway.  Very nice pic, you deserve it for all the hard work you put into this and the other challenges.  - Inspzil</td>', 'Well done Manic.  You''ve officially placed higher than me in a challenge, so I can''t feel like I''ve got one up on you anymore.  I never did feel that way anyway.  Very nice pic, you deserve it for all the hard work you put into this and the other challenges.  - Inspzil', '2002-11-25 04:38:00.000000', NULL, 0),
(157625, 8538, 749, '<td valign="top">I''m now so glad that I decided to go with this idea and not the other one I had :o) I''m shocked that I placed so high, the best I''ve ever done by a long long way (my previous best was last week''s macro challenge, a 6.201)... and thanks for all the great comments - nearly as many on a photo as we used to get back in the early days of DPC! INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
