(157861, 8555, 4615, '<td valign="top">Interesting piece.  I think you may have wanted to zero in on the coke and candy more, making them the focus, perspective is confused.</td>', 'Interesting piece.  I think you may have wanted to zero in on the coke and candy more, making them the focus, perspective is confused.', '2002-11-19 21:09:00.000000', NULL, 1),
(157862, 8555, 4906, '<td valign="top">I liked the idea but didn''t like the lighting or composition. Focus is a bit off too.</td>', 'I liked the idea but didn''t like the lighting or composition. Focus is a bit off too.', '2002-11-20 06:17:00.000000', NULL, 1),
