(158076, 8575, 2700, '<td valign="top">the image needs to be smoother, as gamers jargon goes " jaggies" .... the glasses have very jagged edge. I dont know what kind of camra you have, perhaps you have over sharpend? or blown up the image too big?</td>', 'the image needs to be smoother, as gamers jargon goes " jaggies" .... the glasses have very jagged edge. I dont know what kind of camra you have, perhaps you have over sharpend? or blown up the image too big?', '2002-11-21 21:34:00.000000', NULL, 1),
(158077, 8575, 2716, '<td valign="top">I like it.  Nice bright red colour.  jacko.  7</td>', 'I like it.  Nice bright red colour.  jacko.  7', '2002-11-22 06:26:00.000000', NULL, 1),
(158078, 8575, 1019, '<td valign="top">Great vibrant colour and good design  andrewm</td>', 'Great vibrant colour and good design  andrewm', '2002-11-23 00:06:00.000000', NULL, 1),
(158079, 8575, 4615, '<td valign="top">this is really great!   I hope this wins.</td>', 'this is really great!   I hope this wins.', '2002-11-23 13:50:00.000000', NULL, 1),
