(158088, 8576, 327, '<td valign="top">Very cute idea.</td>', 'Very cute idea.', '2002-11-18 19:00:00.000000', NULL, 1),
(158089, 8576, 2553, '<td valign="top">There''s a lot of "technology" there alright!  I don''t really care for photos of a lot of things all jumbled together.  There doesn''t seem to be anything to focus on- no real subject, and my eyes just keep wanting to jump all over the place.  lhall</td>', 'There''s a lot of "technology" there alright!  I don''t really care for photos of a lot of things all jumbled together.  There doesn''t seem to be anything to focus on- no real subject, and my eyes just keep wanting to jump all over the place.  lhall', '2002-11-18 22:03:00.000000', NULL, 1),
(158090, 8576, 4832, '<td valign="top">Looks totally staged =) No "real" sense to it.</td>', 'Looks totally staged =) No "real" sense to it.', '2002-11-18 23:04:00.000000', NULL, 1),
(158091, 8576, 2223, '<td valign="top">LOL!! looks like my desk!!</td>', 'LOL!! looks like my desk!!', '2002-11-19 11:39:00.000000', NULL, 1),
(158092, 8576, 4648, '<td valign="top">Too cute.  Great idea.  Wonderful sinse of humor.  The humor is the "wow" that makes the difference in a good photo and a great shot.  This has "wow" and is a good photo tech wise also.  Good color, great light, like the crop job, neat subject love the monitors.  I really need the laugh.  Thanks.  PTL</td>', 'Too cute.  Great idea.  Wonderful sinse of humor.  The humor is the "wow" that makes the difference in a good photo and a great shot.  This has "wow" and is a good photo tech wise also.  Good color, great light, like the crop job, neat subject love the monitors.  I really need the laugh.  Thanks.  PTL', '2002-11-19 17:07:00.000000', NULL, 1),
(158093, 8576, 2866, '<td valign="top">I''m guessing your a bachlor. I remember it well. -8-</td>', 'I''m guessing your a bachlor. I remember it well. -8-', '2002-11-19 20:36:00.000000', NULL, 1),
