INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(158101, 8576, 63, '<td valign="top">Is it the technology or the person that''s messy?</td>', 'Is it the technology or the person that''s messy?', '2002-11-23 13:52:00.000000', NULL, 1),
(158102, 8576, 1031, '<td valign="top">How did you sneak into my office?</td>', 'How did you sneak into my office?', '2002-11-23 14:08:00.000000', NULL, 1),
(158103, 8576, 734, '<td valign="top">Looks like you need to buy a KVM switch to clean that up</td>', 'Looks like you need to buy a KVM switch to clean that up', '2002-11-24 22:12:00.000000', NULL, 1),
(158104, 8577, 4625, '<td valign="top">The focus could have been better.</td>', 'The focus could have been better.', '2002-11-18 01:22:00.000000', NULL, 1),
(158105, 8577, 327, '<td valign="top">Wow that''s the truth. Fine idea, well done. Justine</td>', 'Wow that''s the truth. Fine idea, well done. Justine', '2002-11-18 19:00:00.000000', NULL, 1),
(158106, 8577, 772, '<td valign="top">I think that working with the remote control OR the tv would have worked out better in this image... I think your camera flash blew out the hand and remote here... - setzler</td>', 'I think that working with the remote control OR the tv would have worked out better in this image... I think your camera flash blew out the hand and remote here... - setzler', '2002-11-19 13:17:00.000000', NULL, 1),
(158107, 8577, 2343, '<td valign="top">What? the tv? or the remote?  Come on...</td>', 'What? the tv? or the remote?  Come on...', '2002-11-19 16:21:00.000000', NULL, 1),
(158108, 8577, 4648, '<td valign="top">Changed our lives and our marriages and our body fat.  I love this, the humor in it.  I needs a little sharper focus and I''m not real fond of the B &amp; W of this one.  Might have been better in color with the tapes and CD''s.  But I love a good laugh.  and the laugh really gave you a boost.  PTL</td>', 'Changed our lives and our marriages and our body fat.  I love this, the humor in it.  I needs a little sharper focus and I''m not real fond of the B & W of this one.  Might have been better in color with the tapes and CD''s.  But I love a good laugh.  and the laugh really gave you a boost.  PTL', '2002-11-19 18:27:00.000000', NULL, 1),
(158109, 8577, 2170, '<td valign="top">Your DVD of Gladiator changed our lives?</td>', 'Your DVD of Gladiator changed our lives?', '2002-11-19 22:46:00.000000', NULL, 1),
(158110, 8577, 1280, '<td valign="top">I don''t see a whole lot of effort going into this...the subject meets the challenge but it isn''t particularly artistic.  But I realize that''s just my opinion.   The plug, cord, and socket are distracting as are the video tapes, etc.  The flash in the screen is another unecessary element, and the remote isn''t in focus.   Maybe that is intentional, but I''m not sure which is the subject here.  The tv, the remote, or what.  Please understand I am only pointing out my observations.  I know everyione is different, and someone else might love it.  <br/>I think the idea is great, but needs some work.  (Don''t we all) 5 Grayce</td>', 'I don''t see a whole lot of effort going into this...the subject meets the challenge but it isn''t particularly artistic.  But I realize that''s just my opinion.   The plug, cord, and socket are distracting as are the video tapes, etc.  The flash in the screen is another unecessary element, and the remote isn''t in focus.   Maybe that is intentional, but I''m not sure which is the subject here.  The tv, the remote, or what.  Please understand I am only pointing out my observations.  I know everyione is different, and someone else might love it.  I think the idea is great, but needs some work.  (Don''t we all) 5 Grayce', '2002-11-20 00:01:00.000000', NULL, 1),
(158111, 8577, 1005, '<td valign="top">General lack of focus (were you going for soft focus, if so, why?)  Also, not my idea of B&amp;W subject matter.  5 Swash<br/>Joke - could you have at least got some good action on the screen?</td>', 'General lack of focus (were you going for soft focus, if so, why?)  Also, not my idea of B&W subject matter.  5 SwashJoke - could you have at least got some good action on the screen?', '2002-11-20 16:22:00.000000', NULL, 1),
(158112, 8577, 3575, '<td valign="top">I feel this could be a much better photograph if the remote control was clear and sharp and the rest a little out of focus. I believe you''re emphasizing the remote so that would make it better for me.</td>', 'I feel this could be a much better photograph if the remote control was clear and sharp and the rest a little out of focus. I believe you''re emphasizing the remote so that would make it better for me.', '2002-11-20 20:11:00.000000', NULL, 1),
(158113, 8577, 4514, '<td valign="top">The old saying Crack kills is true.  In this case Flash kills.  :-(</td>', 'The old saying Crack kills is true.  In this case Flash kills.  :-(', '2002-11-20 21:45:00.000000', NULL, 1),
(158114, 8577, 2488, '<td valign="top">Lacks focus-bigtime</td>', 'Lacks focus-bigtime', '2002-11-21 07:46:00.000000', NULL, 1),
(158115, 8577, 1255, '<td valign="top">Great idea.  I think it might work better if the remote was in focus and more central in the picture.  The flash on the TV is a bit distracting.</td>', 'Great idea.  I think it might work better if the remote was in focus and more central in the picture.  The flash on the TV is a bit distracting.', '2002-11-21 09:39:00.000000', NULL, 1),
(158116, 8577, 63, '<td valign="top">Was the flash necessary?</td>', 'Was the flash necessary?', '2002-11-23 13:58:00.000000', NULL, 1),
(158117, 8579, 4514, '<td valign="top">Technology yes but too general.</td>', 'Technology yes but too general.', '2002-11-18 01:16:00.000000', NULL, 1),
(158118, 8579, 2344, '<td valign="top">Nice. I''d tweak the colour balance though.. looks too yellowish</td>', 'Nice. I''d tweak the colour balance though.. looks too yellowish', '2002-11-18 07:43:00.000000', NULL, 1),
(158119, 8579, 1856, '<td valign="top">Great idea for tech...would have liked a more interesting composition though.  It''s hard to focus on anything as the ''centerpiece'' in this image.  Lisa</td>', 'Great idea for tech...would have liked a more interesting composition though.  It''s hard to focus on anything as the ''centerpiece'' in this image.  Lisa', '2002-11-18 11:16:00.000000', NULL, 1),
(158120, 8579, 2866, '<td valign="top">I always wondered how all those tanks got filtered. Thanks for sharing this technology with us. -9-</td>', 'I always wondered how all those tanks got filtered. Thanks for sharing this technology with us. -9-', '2002-11-19 19:57:00.000000', NULL, 1),
(158121, 8579, 2170, '<td valign="top">Very nice colors in this image!  The overhead lights are a little hot, but I like the picture overall.</td>', 'Very nice colors in this image!  The overhead lights are a little hot, but I like the picture overall.', '2002-11-19 22:32:00.000000', NULL, 1),
(158122, 8579, 1280, '<td valign="top">There''s no doubt that this meets the challenge.  It has some interesting vertical lines and the blue tanks add color.  The lights send off too much of a glow and dominate the image imo.  Perhaps a tighter crop would appeal to me more.   5  Good luck in the challenge.  Grayce</td>', 'There''s no doubt that this meets the challenge.  It has some interesting vertical lines and the blue tanks add color.  The lights send off too much of a glow and dominate the image imo.  Perhaps a tighter crop would appeal to me more.   5  Good luck in the challenge.  Grayce', '2002-11-19 23:40:00.000000', NULL, 1),
(158123, 8579, 4906, '<td valign="top">The strip lights ruin the picture for me. A lower viewpoint with the lights out of shot would have worked much better.</td>', 'The strip lights ruin the picture for me. A lower viewpoint with the lights out of shot would have worked much better.', '2002-11-20 06:57:00.000000', NULL, 1),
(158124, 8579, 4648, '<td valign="top">Nice shot.  Did a very good job of getting a good shot with their overhead lights.  Real good job.  Just a little, very little, dark but overall great photo.  How did you ever get in ther to get this?  Really good techs.  Like the color.  PTL  Decided this deserved 2 more than I originally gave it.  must have been an off day for me.  You really de deserve the 8.</td>', 'Nice shot.  Did a very good job of getting a good shot with their overhead lights.  Real good job.  Just a little, very little, dark but overall great photo.  How did you ever get in ther to get this?  Really good techs.  Like the color.  PTL  Decided this deserved 2 more than I originally gave it.  must have been an off day for me.  You really de deserve the 8.', '2002-11-21 22:42:00.000000', NULL, 1),
(158125, 8579, 2667, '<td valign="top">this is cool shot... I don''t know what else to say :)</td>', 'this is cool shot... I don''t know what else to say :)', '2002-11-23 00:17:00.000000', NULL, 1),
(158126, 8579, 5070, '<td valign="top">I like this because it shows something we don''t see everyday.</td>', 'I like this because it shows something we don''t see everyday.', '2002-11-23 13:10:00.000000', NULL, 1),
(158127, 8581, 4625, '<td valign="top">Nice lighting on the dome. Amazing blues too. nice shot.</td>', 'Nice lighting on the dome. Amazing blues too. nice shot.', '2002-11-18 00:33:00.000000', NULL, 1),
(158128, 8581, 2344, '<td valign="top">Love it.  I think you may have oversharpened it or something. There''s just something that''s not right about the horizon or the fine detail around the tower.</td>', 'Love it.  I think you may have oversharpened it or something. There''s just something that''s not right about the horizon or the fine detail around the tower.', '2002-11-18 08:08:00.000000', NULL, 1),
(158129, 8581, 3506, '<td valign="top">Excellent composition, bright color(s) and sharpness without excessive oversharpening artifacts.  (8)</td>', 'Excellent composition, bright color(s) and sharpness without excessive oversharpening artifacts.  (8)', '2002-11-18 10:19:00.000000', NULL, 1),
(158130, 8581, 4997, '<td valign="top">wonderful use of colors and shadow.</td>', 'wonderful use of colors and shadow.', '2002-11-18 10:32:00.000000', NULL, 1),
(158131, 8581, 4985, '<td valign="top">Wow. Love the color and contrast.Plus you have great focus on the ball.</td>', 'Wow. Love the color and contrast.Plus you have great focus on the ball.', '2002-11-18 11:18:00.000000', NULL, 1),
(158132, 8581, 2567, '<td valign="top">This is a wow shot.</td>', 'This is a wow shot.', '2002-11-18 14:07:00.000000', NULL, 1),
(158133, 8581, 3127, '<td valign="top">Incredible colors and brightness levels. Very visually appealing photo!</td>', 'Incredible colors and brightness levels. Very visually appealing photo!', '2002-11-18 16:51:00.000000', NULL, 1),
(158134, 8581, 327, '<td valign="top">Not sure what a radome is, but this is very cool. Like it. Justine</td>', 'Not sure what a radome is, but this is very cool. Like it. Justine', '2002-11-18 17:08:00.000000', NULL, 1),
(158135, 8581, 2170, '<td valign="top">Beautiful and exactly on-target for this challenge.  It looks like a painting.  Did you do a longer exposure?</td>', 'Beautiful and exactly on-target for this challenge.  It looks like a painting.  Did you do a longer exposure?', '2002-11-18 17:31:00.000000', NULL, 1),
(158136, 8581, 3669, '<td valign="top">I really like the brilliant blue sky</td>', 'I really like the brilliant blue sky', '2002-11-18 18:31:00.000000', NULL, 1),
(158137, 8581, 4267, '<td valign="top">great color! I like how the foreground is dark... very nice work... top photo of the week I think<br/>~anachronite</td>', 'great color! I like how the foreground is dark... very nice work... top photo of the week I think~anachronite', '2002-11-18 18:32:00.000000', NULL, 1),
(158138, 8581, 3018, '<td valign="top">Wow!  What is the dome for?  Nice image, colors and contrast. Seems a bit soft on the sky, did you use NeatImage on this?</td>', 'Wow!  What is the dome for?  Nice image, colors and contrast. Seems a bit soft on the sky, did you use NeatImage on this?', '2002-11-18 19:23:00.000000', NULL, 1),
(158139, 8581, 3716, '<td valign="top">Very rich blue.. I like!</td>', 'Very rich blue.. I like!', '2002-11-18 19:39:00.000000', NULL, 1),
(158140, 8581, 4388, '<td valign="top">the blue is a tad overdone but the rest of the composition is really nice.<br/></td>', 'the blue is a tad overdone but the rest of the composition is really nice.', '2002-11-18 20:31:00.000000', NULL, 1),
(158141, 8581, 4832, '<td valign="top">Nice blue! You used a filter or post-processing, didn''t you?</td>', 'Nice blue! You used a filter or post-processing, didn''t you?', '2002-11-18 22:51:00.000000', NULL, 1),
(158142, 8581, 2866, '<td valign="top">Well lit. Good comp. -8-</td>', 'Well lit. Good comp. -8-', '2002-11-19 20:23:00.000000', NULL, 1),
(158143, 8581, 2716, '<td valign="top">Super shot.  I love love bright colours, and you got it.  Nice saturation.    Excellent silhouettes, but with the ball nicely lit.  I''ll give it a 10.  Jacko</td>', 'Super shot.  I love love bright colours, and you got it.  Nice saturation.    Excellent silhouettes, but with the ball nicely lit.  I''ll give it a 10.  Jacko', '2002-11-20 06:23:00.000000', NULL, 1),
(158144, 8581, 4906, '<td valign="top">Nice image. Nice colours. Looks like it has been a bit overdone in neatimage though, the clouds look artificially soft. Apologies if that was the intention.</td>', 'Nice image. Nice colours. Looks like it has been a bit overdone in neatimage though, the clouds look artificially soft. Apologies if that was the intention.', '2002-11-20 07:03:00.000000', NULL, 1),
(158145, 8581, 4610, '<td valign="top">Thanks for this wonderful picture..8-morterin</td>', 'Thanks for this wonderful picture..8-morterin', '2002-11-20 14:28:00.000000', NULL, 1),
(158146, 8581, 811, '<td valign="top">very cool.  I like the colors (all three of ''em!) and the contrast.  karmat</td>', 'very cool.  I like the colors (all three of ''em!) and the contrast.  karmat', '2002-11-20 15:07:00.000000', NULL, 1),
(158147, 8581, 1005, '<td valign="top">One heck of a nice photo!  The clouds are great!!!  And the deep blue sky, perfect!  The only reason I''m not going for a 10 here is the bottom, I feel it could have used more cropping.  Oh yes, the trees, very cool, I would have liked to have seen more of them.  9 Swash  (perhaps a landscape view instead of portrait?)</td>', 'One heck of a nice photo!  The clouds are great!!!  And the deep blue sky, perfect!  The only reason I''m not going for a 10 here is the bottom, I feel it could have used more cropping.  Oh yes, the trees, very cool, I would have liked to have seen more of them.  9 Swash  (perhaps a landscape view instead of portrait?)', '2002-11-20 15:13:00.000000', NULL, 1),
(158148, 8581, 4648, '<td valign="top">Beautiful scenery.  1/3s works well here.  I like the color, including the foreground.  Focus is good.  Good composition.  Lacks something but I''m not sure exactly what.  If I figure it out, I''ll come back a let you know.  Otherwise good shot.  PTL  Got back to tell you what it lacks and decided it was me not the photo, so I''m adding 2 points to give you an 8.  Sorry about my mistake.</td>', 'Beautiful scenery.  1/3s works well here.  I like the color, including the foreground.  Focus is good.  Good composition.  Lacks something but I''m not sure exactly what.  If I figure it out, I''ll come back a let you know.  Otherwise good shot.  PTL  Got back to tell you what it lacks and decided it was me not the photo, so I''m adding 2 points to give you an 8.  Sorry about my mistake.', '2002-11-20 17:56:00.000000', NULL, 1),
