(158247, 8589, 2866, '<td valign="top">Good point. -8-</td>', 'Good point. -8-', '2002-11-19 21:00:00.000000', NULL, 1),
(158248, 8589, 4648, '<td valign="top">A tad too dark.  I would love to have been able to see the individual items along with them lit up.  Great idea good execution.  Just need a little more light for me.  Other wise, good shot.  Good focus.  Like the curve of the layout.  PTL</td>', 'A tad too dark.  I would love to have been able to see the individual items along with them lit up.  Great idea good execution.  Just need a little more light for me.  Other wise, good shot.  Good focus.  Like the curve of the layout.  PTL', '2002-11-20 00:10:00.000000', NULL, 1),
(158249, 8589, 4210, '<td valign="top">Great idea. I would have chosen a different colour to contrast a little more.</td>', 'Great idea. I would have chosen a different colour to contrast a little more.', '2002-11-20 02:38:00.000000', NULL, 1),
(158250, 8589, 4517, '<td valign="top">have you ever thought about getting one of those all in one controllers . lol . 6 marbo</td>', 'have you ever thought about getting one of those all in one controllers . lol . 6 marbo', '2002-11-20 04:02:00.000000', NULL, 1),
(158251, 8589, 811, '<td valign="top">The first question that came to my mind was "How did they get all those different remote controls!"  Good lighting and  composition, though it seems a little static.  Maybe a lower camera perspective would have added some interest. karmat</td>', 'The first question that came to my mind was "How did they get all those different remote controls!"  Good lighting and  composition, though it seems a little static.  Maybe a lower camera perspective would have added some interest. karmat', '2002-11-20 13:25:00.000000', NULL, 1),
(158252, 8589, 4514, '<td valign="top">Cute.  Good for not getting a glare from the light.  Have not seen many diffuse the light.</td>', 'Cute.  Good for not getting a glare from the light.  Have not seen many diffuse the light.', '2002-11-20 21:55:00.000000', NULL, 1),
(158253, 8589, 1019, '<td valign="top">Very humourous--a great comment on a modern social dilemma!  andrewm</td>', 'Very humourous--a great comment on a modern social dilemma!  andrewm', '2002-11-21 23:27:00.000000', NULL, 1),
