(158272, 8590, 4832, '<td valign="top">Heh.</td>', 'Heh.', '2002-11-18 23:08:00.000000', NULL, 1),
(158273, 8590, 4648, '<td valign="top">It''s coming to it.  Thank you for the laugh.  We''ve been needing that for sometime.  Technically the only thing that bothers be is the tight crop.  I happen to like to see all of something unless it detracts from  It.  this wouldn''t have.  I like the nice clear focus and colors.  also my favorite cereal.  Great job - great photo - great laugh.  PTL  Thanks</td>', 'It''s coming to it.  Thank you for the laugh.  We''ve been needing that for sometime.  Technically the only thing that bothers be is the tight crop.  I happen to like to see all of something unless it detracts from  It.  this wouldn''t have.  I like the nice clear focus and colors.  also my favorite cereal.  Great job - great photo - great laugh.  PTL  Thanks', '2002-11-19 16:32:00.000000', NULL, 1),
(158274, 8590, 5088, '<td valign="top">Clever idea. I love it! :)</td>', 'Clever idea. I love it! :)', '2002-11-19 20:19:00.000000', NULL, 1),
