(158280, 8590, 2752, '<td valign="top">very clever compsition and sharp photography(8)</td>', 'very clever compsition and sharp photography(8)', '2002-11-20 20:56:00.000000', NULL, 1),
(158281, 8590, 811, '<td valign="top">Great composition and subject.  Very effective use of humor, too.  I wish the money to pay the bills for those things also came in cereal boxes!!!!  karmat</td>', 'Great composition and subject.  Very effective use of humor, too.  I wish the money to pay the bills for those things also came in cereal boxes!!!!  karmat', '2002-11-22 15:37:00.000000', NULL, 1),
