(158290, 8591, 2989, '<td valign="top">Not sure hy you inverted this, would look more pleasing the original way it was shot.  Good luck (you will need it)</td>', 'Not sure hy you inverted this, would look more pleasing the original way it was shot.  Good luck (you will need it)', '2002-11-22 09:16:00.000000', NULL, 1),
(158291, 8591, 4275, '<td valign="top">Quite possibly the best shot ever taken well done. 10 from the slimharpo machine.</td>', 'Quite possibly the best shot ever taken well done. 10 from the slimharpo machine.', '2002-11-22 16:59:00.000000', NULL, 1),
(158292, 8592, 811, '<td valign="top">The perspective of this is awesome, almost dizzy-ing.  Maybe cropping out a tiny slice of the bottom, so the opening of the boat doesn''t show, would have been more effective.  Great work, still. karmat</td>', 'The perspective of this is awesome, almost dizzy-ing.  Maybe cropping out a tiny slice of the bottom, so the opening of the boat doesn''t show, would have been more effective.  Great work, still. karmat', '2002-11-18 00:48:00.000000', NULL, 1),
(158293, 8592, 674, '<td valign="top">Technically correct , exposure, focus, saturation , contrast. 5<br/>Good composition.  <br/>Tells a story or creates a mood <br/>      Impact to the viewer <br/>Relevance to the Challenge 5<br/>Overall 5<br/>sulamk<br/></td>', 'Technically correct , exposure, focus, saturation , contrast. 5Good composition.  Tells a story or creates a mood       Impact to the viewer Relevance to the Challenge 5Overall 5sulamk', '2002-11-18 00:51:00.000000', NULL, 1),
(158294, 8592, 2344, '<td valign="top">Nice colours. Although I get the impression this is meant to be a landscape image rather than a statement about technology.</td>', 'Nice colours. Although I get the impression this is meant to be a landscape image rather than a statement about technology.', '2002-11-18 07:40:00.000000', NULL, 1),
(158295, 8592, 327, '<td valign="top">Great perspective shot, wonderful colors. Maybe a tighter crop on the left or more of the boat. &amp;lt;?&amp;gt; Justine.</td>', 'Great perspective shot, wonderful colors. Maybe a tighter crop on the left or more of the boat. &lt;?&gt; Justine.', '2002-11-18 17:01:00.000000', NULL, 1),
(158296, 8592, 4648, '<td valign="top">I love the scenery but there sure is an awful lot of "stuff" floating on the water.  Not only low tech travel, but also slow tech travel.  Relaxes me.  A little dark at the boat but still a real good shot.  Nice 6.  PTL</td>', 'I love the scenery but there sure is an awful lot of "stuff" floating on the water.  Not only low tech travel, but also slow tech travel.  Relaxes me.  A little dark at the boat but still a real good shot.  Nice 6.  PTL', '2002-11-18 20:44:00.000000', NULL, 1),
(158297, 8592, 4832, '<td valign="top">Really pretty water - kinda forced into the theme though, isn''t it?</td>', 'Really pretty water - kinda forced into the theme though, isn''t it?', '2002-11-18 23:10:00.000000', NULL, 1),
(158298, 8592, 2866, '<td valign="top">... in a high tech world. -8-</td>', '... in a high tech world. -8-', '2002-11-19 20:12:00.000000', NULL, 1),
