INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(158301, 8592, 1280, '<td valign="top">Nice picture and it IS technology.  Some people may not see it that way but I think you expect that when you submit an image that doesn''t immediately associate with technology.  <br/>I like it...good luck!<br/>Grayce</td>', 'Nice picture and it IS technology.  Some people may not see it that way but I think you expect that when you submit an image that doesn''t immediately associate with technology.  I like it...good luck!Grayce', '2002-11-20 17:32:00.000000', NULL, 1),
(158302, 8592, 4969, '<td valign="top">cool perspective! and shadows</td>', 'cool perspective! and shadows', '2002-11-20 23:32:00.000000', NULL, 1),
(158303, 8592, 2586, '<td valign="top">Even though i''m not voting, i like to comment on this picture as i have a hunch  who submitted it. I like the originality of the submission and see how it meets the challenge but maybe  that''s because i''m very smart ;)  I see two pictures here: the top part, which i find rather boring, was included to tie it into your challenge theme. The bottom half of the picture is the part that i really like. It''s very emotional and evocative and it gives me the sensation of being right there in that boat on the water and being able to stick my hand out and feel the water. If the top part hadn''t been included, the lighting in the bottom left could have been better as well. Too bad the water and the boat are the same color. Had i voted, would have given this a 7. I couldn''t possibly begin to guess in what part of the world  this was taken but wow what a lot of trees :) Journey</td>', 'Even though i''m not voting, i like to comment on this picture as i have a hunch  who submitted it. I like the originality of the submission and see how it meets the challenge but maybe  that''s because i''m very smart ;)  I see two pictures here: the top part, which i find rather boring, was included to tie it into your challenge theme. The bottom half of the picture is the part that i really like. It''s very emotional and evocative and it gives me the sensation of being right there in that boat on the water and being able to stick my hand out and feel the water. If the top part hadn''t been included, the lighting in the bottom left could have been better as well. Too bad the water and the boat are the same color. Had i voted, would have given this a 7. I couldn''t possibly begin to guess in what part of the world  this was taken but wow what a lot of trees :) Journey', '2002-11-21 23:29:00.000000', NULL, 1),
(158304, 8592, 1019, '<td valign="top">Beautiful photo--the water is smooth and the ripples clean --colour beautiful --well done  andrewm</td>', 'Beautiful photo--the water is smooth and the ripples clean --colour beautiful --well done  andrewm', '2002-11-23 00:02:00.000000', NULL, 1),
(158305, 8592, 1792, '<td valign="top">Good idea, but it seems that the subject of the picture in the foreground  needs to stand out from the background more.  It just sort of blends in and the eye is pulled away by the background skyline.  Composition and focus are nice.</td>', 'Good idea, but it seems that the subject of the picture in the foreground  needs to stand out from the background more.  It just sort of blends in and the eye is pulled away by the background skyline.  Composition and focus are nice.', '2002-11-23 11:27:00.000000', NULL, 1),
(158306, 8592, 2586, '<td valign="top">Hehehe, i guessed that right! Seeing this picture again, i  take it back that the top part is boring. Sorry.  It''s quite a nice picture overall.</td>', 'Hehehe, i guessed that right! Seeing this picture again, i  take it back that the top part is boring. Sorry.  It''s quite a nice picture overall.', '2002-11-25 00:55:00.000000', NULL, 0),
(158307, 8592, 2923, '<td valign="top">oh well :) most people don''t get it, that''s too bad :)</td>', 'oh well :) most people don''t get it, that''s too bad :)', '2002-11-25 12:39:00.000000', NULL, 0),
(158308, 8593, 2344, '<td valign="top">Oh! Dont forget to sneak in that sunset picture!</td>', 'Oh! Dont forget to sneak in that sunset picture!', '2002-11-18 07:42:00.000000', NULL, 1),
(158309, 8593, 4536, '<td valign="top">I too shot some electrical towers, glad I didn''t submit them, this one is much stronger.<br/>I like the pastel colors and the composition.</td>', 'I too shot some electrical towers, glad I didn''t submit them, this one is much stronger.I like the pastel colors and the composition.', '2002-11-18 13:16:00.000000', NULL, 1),
(158310, 8593, 2567, '<td valign="top">Wow.  Nice shot</td>', 'Wow.  Nice shot', '2002-11-18 14:17:00.000000', NULL, 1),
(158311, 8593, 4495, '<td valign="top">the red cast doesn''t seem to do justice to this picture -- the blue sky should pop through more imho</td>', 'the red cast doesn''t seem to do justice to this picture -- the blue sky should pop through more imho', '2002-11-18 23:36:00.000000', NULL, 1),
(158312, 8593, 3142, '<td valign="top">hey, they do look like giants with arms and legs.. coolios!</td>', 'hey, they do look like giants with arms and legs.. coolios!', '2002-11-18 23:46:00.000000', NULL, 1),
(158313, 8593, 5202, '<td valign="top">The colors are absolutely marvelous (did you use a filter?), however, I think it could be brightened a bit to make it more striking, but still excellent.<br/>(dont take my advice though, because I am just beginning the whole photography thing)<br/></td>', 'The colors are absolutely marvelous (did you use a filter?), however, I think it could be brightened a bit to make it more striking, but still excellent.(dont take my advice though, because I am just beginning the whole photography thing)', '2002-11-19 15:44:00.000000', NULL, 1),
(158314, 8593, 2866, '<td valign="top">... or necessary evil? -7-</td>', '... or necessary evil? -7-', '2002-11-19 20:29:00.000000', NULL, 1),
(158315, 8593, 4210, '<td valign="top">I like the colour - did you adjust it, or is it natural?</td>', 'I like the colour - did you adjust it, or is it natural?', '2002-11-20 02:31:00.000000', NULL, 1),
(158316, 8593, 4906, '<td valign="top">Could be a little sharper or more contrasty as some of the cables are a bit lost in the background.</td>', 'Could be a little sharper or more contrasty as some of the cables are a bit lost in the background.', '2002-11-20 06:11:00.000000', NULL, 1),
(158317, 8593, 4648, '<td valign="top">Why did you ruin a beautiful picture by turning it red?  What blue I can see coming through must have been beautiful.  Again.  Personally I think you have ruined an 8 or above shot.  I know it was beautiful with "wow".  But now.....PTL  Can''t help but come back.  Can''t give you the 8 but sure deserves more than the 4.  How about let''s split it at 7.  Without the color change it would have been moved up to a 10.  But 7 is mighty good score.</td>', 'Why did you ruin a beautiful picture by turning it red?  What blue I can see coming through must have been beautiful.  Again.  Personally I think you have ruined an 8 or above shot.  I know it was beautiful with "wow".  But now.....PTL  Can''t help but come back.  Can''t give you the 8 but sure deserves more than the 4.  How about let''s split it at 7.  Without the color change it would have been moved up to a 10.  But 7 is mighty good score.', '2002-11-20 18:08:00.000000', NULL, 1),
