(158540, 8613, 327, '<td valign="top">Really a neat shot. Fun. Justine</td>', 'Really a neat shot. Fun. Justine', '2002-11-18 17:06:00.000000', NULL, 1),
(158541, 8613, 4267, '<td valign="top">try this with no flash and a longer shutter speed to let some light in... I bet there would be some cool shadows in that cubbie hole<br/>~anachronite<br/></td>', 'try this with no flash and a longer shutter speed to let some light in... I bet there would be some cool shadows in that cubbie hole~anachronite', '2002-11-18 18:27:00.000000', NULL, 1),
