(158544, 8613, 2716, '<td valign="top">Is that how that works?  Nice angle.  jacko</td>', 'Is that how that works?  Nice angle.  jacko', '2002-11-21 19:48:00.000000', NULL, 1),
(158545, 8613, 2667, '<td valign="top">one of the more inventive pics I have seen. very interesting subject matter you have portrayed here!</td>', 'one of the more inventive pics I have seen. very interesting subject matter you have portrayed here!', '2002-11-23 00:17:00.000000', NULL, 1),
(158546, 8613, 4648, '<td valign="top">Not many people have worked in a bowling alley and seen this part ot the technology.  Great shot and I think it is of good interest.  Not a "wow" but interesting.  Focus is good.  Crop job good.  Colors are good.  Meets technical challenge well.  Overall good shot.  PTL  After another decided the shot really deserves a couple more points so here''s an 8.</td>', 'Not many people have worked in a bowling alley and seen this part ot the technology.  Great shot and I think it is of good interest.  Not a "wow" but interesting.  Focus is good.  Crop job good.  Colors are good.  Meets technical challenge well.  Overall good shot.  PTL  After another decided the shot really deserves a couple more points so here''s an 8.', '2002-11-23 17:41:00.000000', NULL, 1),
(158547, 8614, 4906, '<td valign="top">Nice take on the subject. Good colours.</td>', 'Nice take on the subject. Good colours.', '2002-11-18 08:25:00.000000', NULL, 1),
(158548, 8614, 327, '<td valign="top">They start them young these days. Nice colors......good old Fisher Price! Creative work. Justine</td>', 'They start them young these days. Nice colors......good old Fisher Price! Creative work. Justine', '2002-11-18 17:09:00.000000', NULL, 1),
(158549, 8614, 4821, '<td valign="top">Maybe a little too sharpened.  And the light and the angle make it kind of creepy looking.  Needs a happier background</td>', 'Maybe a little too sharpened.  And the light and the angle make it kind of creepy looking.  Needs a happier background', '2002-11-18 18:53:00.000000', NULL, 1),
(158550, 8614, 4648, '<td valign="top">We all need to get back to such clear, sharp, wonderful colored right on, near perfect childish fun.  Just don''t cut off any of our toys the next time.  This is so much fun and I don''t want to miss any of it.  It''s to good.  PTL</td>', 'We all need to get back to such clear, sharp, wonderful colored right on, near perfect childish fun.  Just don''t cut off any of our toys the next time.  This is so much fun and I don''t want to miss any of it.  It''s to good.  PTL', '2002-11-19 02:07:00.000000', NULL, 1),
(158551, 8614, 1280, '<td valign="top">Good colors, focus is fine, meets the challenge.  Composition is ok.  Subject is so so.  But of course to a toddler is very COOL!  6 Good luck in the challenge!  Grayce</td>', 'Good colors, focus is fine, meets the challenge.  Composition is ok.  Subject is so so.  But of course to a toddler is very COOL!  6 Good luck in the challenge!  Grayce', '2002-11-20 14:34:00.000000', NULL, 1),
(158552, 8614, 3532, '<td valign="top">I think a different background - something with some light and color in it would have been better for this shot than the black.  The black is too somber to go with a kid''s toy - unless you were intentionall trying for that contrast?</td>', 'I think a different background - something with some light and color in it would have been better for this shot than the black.  The black is too somber to go with a kid''s toy - unless you were intentionall trying for that contrast?', '2002-11-20 20:55:00.000000', NULL, 1),
(158553, 8614, 4514, '<td valign="top">Light is very harsh.  Need to keep the same intensity but use a piece of white cloth in front of light source to soften it up.,  this way here there is not glare.  <br/></td>', 'Light is very harsh.  Need to keep the same intensity but use a piece of white cloth in front of light source to soften it up.,  this way here there is not glare.  ', '2002-11-20 21:25:00.000000', NULL, 1),
(158554, 8614, 4615, '<td valign="top">nice colors.</td>', 'nice colors.', '2002-11-20 22:21:00.000000', NULL, 1),
(158555, 8614, 3900, '<td valign="top">Nice focus, but it looks a bit jaggy, maybe too much sharpen applied...looks like the focus was already there, so no need to sharpen ...hmm yes kids toys have come a long way haven''t they.</td>', 'Nice focus, but it looks a bit jaggy, maybe too much sharpen applied...looks like the focus was already there, so no need to sharpen ...hmm yes kids toys have come a long way haven''t they.', '2002-11-21 03:56:00.000000', NULL, 1),
