(159095, 8650, 5070, '<td valign="top">Should be disqualified as having nothing to do with technology.</td>', 'Should be disqualified as having nothing to do with technology.', '2002-11-23 14:37:00.000000', NULL, 1),
(159096, 8650, 5096, '<td valign="top">Love it!  Some technology cannot be improved upon.  8</td>', 'Love it!  Some technology cannot be improved upon.  8', '2002-11-24 21:30:00.000000', NULL, 1),
