(159099, 8651, 2011, '<td valign="top">This is a good capture, but I think the background takes away from the overall appeal of the  picture.6 boyte1</td>', 'This is a good capture, but I think the background takes away from the overall appeal of the  picture.6 boyte1', '2002-11-18 01:24:00.000000', NULL, 1),
