(159101, 8651, 2344, '<td valign="top">Red is distracting. Use a white or black for best effect.</td>', 'Red is distracting. Use a white or black for best effect.', '2002-11-18 08:08:00.000000', NULL, 1),
(159102, 8651, 327, '<td valign="top">Super idea, super shot. Just not crazy for the lighting here w/this red background. I know we work with what we got!  This light is just too strong or too bright. I love the arrows and the idea is wonderful. O'' also....the shadows are great!! Justine.</td>', 'Super idea, super shot. Just not crazy for the lighting here w/this red background. I know we work with what we got!  This light is just too strong or too bright. I love the arrows and the idea is wonderful. O'' also....the shadows are great!! Justine.', '2002-11-18 19:42:00.000000', NULL, 1),
(159103, 8651, 4210, '<td valign="top">I would have tried a different colour background to bring out the contrast more.</td>', 'I would have tried a different colour background to bring out the contrast more.', '2002-11-19 00:44:00.000000', NULL, 1),
(159104, 8651, 4411, '<td valign="top">Great detail on the flights but not keen on the background. Too ''loud'' for my taste.</td>', 'Great detail on the flights but not keen on the background. Too ''loud'' for my taste.', '2002-11-19 18:44:00.000000', NULL, 1),
(159105, 8651, 4615, '<td valign="top">I like this composition, it could stand toning down the intensity a little.</td>', 'I like this composition, it could stand toning down the intensity a little.', '2002-11-19 21:27:00.000000', NULL, 1),
(159106, 8651, 1005, '<td valign="top">Very well taken shot.  The strips of glare might hurt your overall score, but the bright set up may counter-balance that.  9 Swash</td>', 'Very well taken shot.  The strips of glare might hurt your overall score, but the bright set up may counter-balance that.  9 Swash', '2002-11-20 15:22:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(159107, 8651, 4648, '<td valign="top">I said it before and I''ll say it again, I don''t like the red shots at all.  To me you have ruined a perfectly good shot with it.  Everything is sharp, the colors on the arrows are great.  Not too bad of a crop job.  Met the challenge but you ruined it with the "RED".  You lost at least 3 maybe 4 points for it in my eyes.  Sorry.  Just my personal opinion.  PTL  If your picture hadn''t had as much techs going for it, it would have scored a lot lower.</td>', 'I said it before and I''ll say it again, I don''t like the red shots at all.  To me you have ruined a perfectly good shot with it.  Everything is sharp, the colors on the arrows are great.  Not too bad of a crop job.  Met the challenge but you ruined it with the "RED".  You lost at least 3 maybe 4 points for it in my eyes.  Sorry.  Just my personal opinion.  PTL  If your picture hadn''t had as much techs going for it, it would have scored a lot lower.', '2002-11-20 17:35:00.000000', NULL, 1),
(159108, 8651, 4514, '<td valign="top">Nice but need to adjust the whitebalance I think the red pencil looks a little orange.</td>', 'Nice but need to adjust the whitebalance I think the red pencil looks a little orange.', '2002-11-20 22:03:00.000000', NULL, 1),
(159109, 8651, 3900, '<td valign="top">I don''t see how becoming sport from necessity is related to technology. Their inception was a technological advance in hunting way back in the past, and their design and production has certainly advanced in recent times.  But they are still used for hunting, so I just don''t get your title.  Anyway, decent shot, but I think it would be better with more depth of field, i.e. more focus all around.</td>', 'I don''t see how becoming sport from necessity is related to technology. Their inception was a technological advance in hunting way back in the past, and their design and production has certainly advanced in recent times.  But they are still used for hunting, so I just don''t get your title.  Anyway, decent shot, but I think it would be better with more depth of field, i.e. more focus all around.', '2002-11-21 04:45:00.000000', NULL, 1),
(159110, 8651, 1255, '<td valign="top">Love the red background here, very eye catching.  Good macro on the arrows.</td>', 'Love the red background here, very eye catching.  Good macro on the arrows.', '2002-11-21 09:40:00.000000', NULL, 1),
(159111, 8651, 2716, '<td valign="top">Great colours!  I like it. jacko  8</td>', 'Great colours!  I like it. jacko  8', '2002-11-21 19:52:00.000000', NULL, 1),
(159112, 8651, 1280, '<td valign="top">Yep...very true.  Nicely composed and good lighting, and dof.  Good luck in the challenge.  Grayce  :-)</td>', 'Yep...very true.  Nicely composed and good lighting, and dof.  Good luck in the challenge.  Grayce  :-)', '2002-11-21 23:55:00.000000', NULL, 1),
(159113, 8651, 5149, '<td valign="top">Nice sharp image and good lighting.</td>', 'Nice sharp image and good lighting.', '2002-11-22 21:31:00.000000', NULL, 1),
(159114, 8653, 4906, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2002-11-18 09:41:00.000000', NULL, 1),
